void verify_user_pass(struct user_pass *up, struct tls_multi *multi, struct tls_session *session)
{
    int s1 = OPENVPN_PLUGIN_FUNC_SUCCESS;
    bool s2 = true;
    struct key_state *ks = &session->key[KS_PRIMARY];

    if (session->opt->auth_token_generate && is_auth_token(up->password))
    {
        ks->auth_token_state_flags = verify_auth_token(up, multi, session);
        if (session->opt->auth_token_call_auth)
        {
            /* we do not care about the result here because it is the responsibility of the external authentication to decide what to do with the result */
        }
        else if (ks->auth_token_state_flags == AUTH_TOKEN_HMAC_OK)
        {
            msg(M_WARN, "TLS: Username/auth-token authentication succeeded for username '%s'", up->username);
            skip_auth = true;
        }
        else
        {
            wipe_auth_token(multi);
            ks->authenticated = KS_AUTH_FALSE;
            msg(M_WARN, "TLS: Username/auth-token authentication failed for username '%s'", up->username);
            return;
        }
    }

    if (!set_verify_user_pass_env(up, multi, session))
    {
